from astroid import exceptions, nodes

    def test_attr_with_only_annotation_fails(self) -> None:
        code = """
        import attr

        @attr.s
        class Foo:
            bar: int
        Foo()
        """
        with self.assertRaises(exceptions.AttributeInferenceError):
            next(astroid.extract_node(code).infer()).getattr("bar")

    def test_attrs_with_only_annotation_works(self) -> None:
        code = """
        import attrs

        @attrs.define
        class Foo:
            bar: int
            baz: str = "hello"
        Foo(1)
        """
        for attr_name in ("bar", "baz"):
            should_be_unknown = next(astroid.extract_node(code).infer()).getattr(
                attr_name
            )[0]
            self.assertIsInstance(should_be_unknown, astroid.Unknown)

from attr._compat import PY310, PY_3_8_PLUS
    @pytest.mark.skipif(not PY_3_8_PLUS, reason="cached_property is 3.8+")
    def test_no_references_to_original_when_using_cached_property(self):
        """
        When subclassing a slotted class and using cached property, there are no stray references to the original class.
        """

        @attr.s(slots=True)
        class C:
            pass

        @attr.s(slots=True)
        class C2(C):
            @functools.cached_property
            def value(self) -> int:
                return 0

        # The original C2 is in a reference cycle, so force a collect:
        gc.collect()

        assert [C2] == C.__subclasses__()

@pytest.mark.skipif(not PY_3_8_PLUS, reason="cached_property is 3.8+")
def test_slotted_cached_property_can_access_super():
    """
    Multiple sub-classes shouldn't break cached properties.
    """

    @attr.s(slots=True)
    class A:
        x = attr.ib(kw_only=True)

    @attr.s(slots=True)
    class B(A):
        @functools.cached_property
        def f(self):
            return super().x * 2

    assert B(x=1).f == 2

